export const AGENT_TEMPLATES: AgentTemplate[] = [...BASE_TEMPLATES, ...ELITE_TEMPLATES];

/** A template as a ready agent, in the interface language. A template without a fixed jurisdiction follows the
 *  workspace's chosen one; when none is chosen it stays unset («»), and the agent asks for one before it runs. */
export function templateAgent(template: AgentTemplate, english: boolean, now = Date.now(), fallback = ''): AgentDefinition {
  const pick = (value: L) => english ? value.en : value.el;
  return { id: `ready-${template.id}`, field: 'legal', name: pick(template.name), description: pick(template.description), category: template.category,
    instructions: template.instructions, starters: (starters => english ? starters.en : starters.el)(AGENT_STARTERS[template.id] ?? template.starters), needs: pick(template.needs),
    jurisdiction: template.jurisdiction ?? fallback, officialSearch: template.officialSearch ?? false, mode: template.mode ?? 'fast',
    knowledge: [], origin: 'ready', createdAt: now, updatedAt: now };
}
